'use strict';
/* public/js/74-landslide.js -- landslides: deterministic boulder physics, hits, warnings. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- landslide (rockslide) hazard ---------- */
/* Boulders come tumbling down off Big Thumb's side (TH_X/TH_Z, above) and bound across the lake through the slide's
   spot: a handful of big ones, one steady pace, hop by hop (see the JT note at LS_N_MIN below). Two ways one starts: the "landslide" console
   command (aimed at you, shared over the env relay exactly like the twister command), and natural ones that happen
   on their own -- picked out from the shared clock + a seed the same way natural twisters are (see lsPlan below),
   weighted to happen more often on Big Thumb's side of the lake (z<0).
   Determinism: every boulder is stepped with a FIXED timestep (LS_DT), from a seeded RNG and its own burst's origin
   time, using baseH() -- the pure noise height, not groundAt() -- for the ground under it. Each burst's boulders are
   stepped in lockstep AS A GROUP, one LS_DT tick at a time, all sharing one clock (see lsClock in updateLandslides),
   with a boulder-boulder collision pass (lsKnock) run after every tick -- so a knock always compares two boulders
   at the exact same simulated instant, for every camper, regardless of framerate or catch-up batching (gating each
   boulder by its own independent catch-up need instead would let two boulders in the same burst drift out of sync
   within a single real frame, and a knock computed from that would disagree between clients). Different bursts
   never interact and are processed one at a time, so their timing can't leak into each other either. Any
   "liveliness" -- ricochet kicks on
   bounce, which boulders knock which -- comes from a per-boulder seed hash (hash2) or from the two boulders' own
   physical state, never from Math.random() or shared mutable RNG state (whose draw order would depend on how many
   steps a late joiner's catch-up needed, and desync between clients). Camera shake, dust puffs and the landing
   whistle are pure local eye-candy keyed off that same deterministic state, so they never touch it back.
   groundAt() would disagree camper to camper wherever someone's dug a hole nearby (it depends on which chunks are
   loaded, a per-player, per-frame thing), so it's used only for render positions -- boulders, the ground-danger
   marker -- never for physics. */
const LS_DT=1/60;                    // physics step (s): fixed, so results don't depend on the render frame rate
const LS_MAX_STEPS=600;              // most steps run in one real frame (10 sim-seconds) -- caps the catch-up burst for a late joiner
const LS_LIVE_STEP_CAP=24;           // fewer than this many needed steps this frame = "live" play; more = a catch-up replay, so skip FX (dust/shake/thud/whistle) but keep the physics identical either way
/* JT 2026-09-30: "the rocks just look glitchy. Some go super fast and some way too slow. Take a note from the tumbleweed
   book: some big rocks bouncing and moving a little bit slower." So a slide is now a handful of BIG boulders that come
   tumbling down off Big Thumb's side and bound across the lake at one steady, readable pace (6.5-10 m/s, the big ones
   a touch slower), hop by hop, then run out of steam and settle. (It was 30-48 rocks dropped from 120 m, half of them
   flung in at up to ~60 m/s while the rest crawled.) */
const LS_N_MIN=8, LS_N_MAX=14;       // boulders in a slide
const LS_R_MIN=0.9, LS_R_MAX=2.3;    // boulder radius (m): all of them big enough to read from a distance
const LS_R_SKEW=1.1;                 // radius = min + range * u^LS_R_SKEW: about even, a few really big ones
const LS_BACK=45, LS_BACK_J=18;      // they start this far upslope (toward Big Thumb) of the slide's spot (m), +/- jitter
const LS_DROP_H=7;                   // ...and this high above the ground (+ up to 6 m): they tumble in, they don't rain
const LS_SPREAD=26;                  // how wide the slide is, across its path (m)
const LS_SPEED_MIN=6.5, LS_SPEED_MAX=10;   // ground speed (m/s): one pace for the whole slide, give or take
const LS_BIG_SLOW=0.25;              // the biggest boulders go this much slower than the smallest
const LS_GRAV=20;                    // gravity for boulders (m/s^2): a touch heavier than the player's 16, lighter than before (26)
const LS_BARRAGE_SPAN=6;             // seconds over which a slide's boulders set off
const LS_BARRAGE_JITTER=1.2;         // +/- seeded jitter (s) on each one's start, so they don't come in a metronome line
const LS_ROLL_TIME=12;               // seconds a boulder keeps its pace (bounding along); after that it runs out of steam and settles
const LS_HOP_MIN=3.4, LS_HOP_R=1.6;  // every bounce kicks it back up at least LS_HOP_MIN + LS_HOP_R x radius (m/s) while it's rolling:
                                     // hops of ~0.6-1.2 m, the big ones bounding higher (the tumbleweed trick: it never just slides)
const LS_REST=0.3;                   // plus this share of the landing speed
const LS_BOUNCE_MAX_UP=9;            // caps a bounce's upward speed (m/s)
const LS_BOUNCE_MIN_VY=0.75;         // a downward speed below this on contact is just settling, not a bounce (must clear LS_GRAV*LS_DT)
const LS_BOUNCE_FRIC=0.97;           // ground speed kept through a bounce
const LS_KICK_CHANCE=0.45;           // chance a bounce knocks it a little sideways (seeded, identical for everyone)
const LS_KICK_SPEED=2;               // ...by up to this (m/s): a wobble in its line, not a ricochet
const LS_FLOOR_FRAC=0.8;             // while rolling, its ground speed doesn't drop below this share of its pace
const LS_ROLL_FRIC=0.25;             // ground friction while rolling (per s)
const LS_STOP_FRIC=1.1;              // ...and once it's run out of steam
const LS_SLOPE_ACCEL=6;              // downhill on the terrain helps a little
const LS_SETTLE_SPEED=0.4;           // ground speed (m/s) below which a boulder counts as "settled"
const LS_SETTLE_TIME=2;              // seconds below LS_SETTLE_SPEED before a rock is fully at rest
const LS_FADE_TIME=6;                // seconds a settled boulder takes to shrink away once it's at rest
const LS_HURT_SPEED=2.2;             // below this speed (m/s) a boulder is too gentle to hurt you -- still solid though
const LS_DMG_K=7;                    // damage = (speed-LS_HURT_SPEED) * radius * LS_DMG_K -- big + fast easily clears 100 (a kill)
const LS_DMG_SPEED_CAP=12;           // damage/knockback math clamps a boulder's speed here -- the faster spawn speeds shouldn't make every hit an auto-kill regardless of size
const LS_HIT_GRACE=1.2;              // seconds of immunity to boulders after being hit, so one rock can't hit you every frame
const LS_TOUCH_PAD=0.55;             // added to a boulder's radius for player<->boulder collision (rough player half-width)
const LS_SAFE_DEPTH=1.2;             // a hole deeper than this (4 ft, same threshold the twister uses) shields you from boulders
const LS_WARN_R=100;                 // being this close (m) to a fresh burst gets you the "Rockslide!" toast -- widened along with the burst's own spread
const LS_WARN_LEAD=0.8;              // seconds of lead time the ground marker + whistle give before a boulder actually lands
const LS_WARN_DIST=85;               // only show a landing marker / play its whistle for a boulder landing within this range of you (readability + keeps 26-boulder bursts from all whistling at once)
const LS_MARK_SCALE0=3.4;            // the landing-danger ring starts this many boulder-radii wide when it first appears...
const LS_MARK_SCALE1=1.05;           // ...and closes in to about the boulder's own footprint right as it lands -- a readable "get out of the ring" telegraph
const LS_SHAKE_R=30;                 // camera shake falls off to nothing by this far (m) from a fresh impact
const LS_SHAKE_MAX=0.28;             // camera shake amplitude (m) for an impact right on top of you
const LS_SHAKE_DECAY=6;              // per-second decay rate of the current camera-shake amplitude
const LS_DUST_N=16;                  // dust particles kicked up on a boulder's first impact (reuses the shared dirt-particle pool)
const LS_DUST_N_BOUNCE=6;            // fewer particles on later bounces/skips -- it's already a dusty rock by then
const LS_KNOCK_REST=0.35;            // restitution for rock-on-rock knocks: enough to send them ricocheting off each other
const LS_POOL_CAP=100;               // max rocks rendered/simulated at once (about two full barrages)
const LS_CELL=220;                   // natural landslides: grid square size (m) -- same idea as the twister's TW_CELL
const LS_WIN=100000;                 // natural landslides: time window per square (ms)
const LS_CHANCE=0.05;                // natural landslides: per-window chance for an ordinary square
const LS_CHANCE_THUMB=0.28;          // per-window chance for a square on Big Thumb's side of the lake (z<0)
const LS_LIFE=40;                    // seconds after t0 a slide is over: 6 s of starts, 12 s rolling, settling, the fade

let lsBoulders=[],lsBursts=[];         // active boulders, and the burst "events" they belong to (for the warning + minimap)
const lsSeen=new Map();                // natural landslide plan-id -> the window k it belongs to, so each plan spawns once
const lsClock=new Map();               // bg (burst origin time) -> that burst's own accumulated simulated seconds, advanced in lockstep for every boulder in it (see updateLandslides)
let lsHitT=0,lsRumbleNode=null,lsLastK=-1,lsShake=0;   // lsShake: current local camera-shake amplitude, decays every frame
const lsAxis=new T.Vector3();          // scratch vector, reused every frame so lsRender() doesn't allocate

/* pure ballistic replay of a boulder's pre-bounce flight (same arithmetic as the top of lsStep, minus the bounce
   itself), used once at spawn to know where and when it will FIRST touch down. Only touches baseH -- deterministic,
   and never consumes the burst's RNG -- so it doesn't disturb the sequence the rest of the burst draws from. */
function lsPredictImpact(x,y,z,vx,vy,vz,r){
  for(let i=0;i<LS_MAX_STEPS;i++){
    vy-=LS_GRAV*LS_DT;x+=vx*LS_DT;y+=vy*LS_DT;z+=vz*LS_DT;
    if(y<=baseH(x,z)+r)return{t:(i+1)*LS_DT,x,z};
  }
  return null;
}

/* one burst: n boulders that share a seed and a burst origin time, so anyone computing the same two numbers gets
   the same rain. Each boulder gets its own slightly later spawn time (t0) so the burst rains down over several
   seconds instead of landing all at once; bg (burst group) stays the shared origin time, used to scope boulder-
   boulder knocks to boulders from the very same burst. */
function spawnLandslide(x,z,seed,t0){
  const r=mulberry32(seed>>>0);r();
  const away=Math.atan2(x-TH_X,z-TH_Z),ux=Math.sin(away),uz=Math.cos(away);   // the slide's direction: off Big Thumb, through (x,z)
  const n=LS_N_MIN+Math.floor(r()*(LS_N_MAX-LS_N_MIN+1)),pace=LS_SPEED_MIN+r()*(LS_SPEED_MAX-LS_SPEED_MIN);
  for(let i=0;i<n&&lsBoulders.length<LS_POOL_CAP;i++){
    const rad=LS_R_MIN+Math.pow(r(),LS_R_SKEW)*(LS_R_MAX-LS_R_MIN),side=(r()*2-1)*LS_SPREAD,back=LS_BACK+(r()*2-1)*LS_BACK_J;
    const bx=x-ux*back+uz*side,bz=z-uz*back-ux*side;
    const sp=pace*(0.9+r()*0.2)*(1-LS_BIG_SLOW*(rad-LS_R_MIN)/(LS_R_MAX-LS_R_MIN)),turn=(r()-0.5)*0.25;   // its own pace and a slight angle off the line
    const bvx=(ux*Math.cos(turn)+uz*Math.sin(turn))*sp,bvz=(uz*Math.cos(turn)-ux*Math.sin(turn))*sp,vy0=-2-r()*3;
    const by=baseH(bx,bz)+rad+LS_DROP_H+r()*6;
    const stagger=Math.max(0,((i+r())/n)*LS_BARRAGE_SPAN+(r()-0.5)*LS_BARRAGE_JITTER);
    const dodeca=r()<0.5,seedB=(r()*4294967296)>>>0;
    const pred=lsPredictImpact(bx,by,bz,bvx,vy0,bvz,rad);
    // stagger (s): this boulder's own delay after the slide's shared clock (bg) starts, before it's "awake" --
    // see updateLandslides, which drives every boulder in a slide off ONE shared simulated clock, not its own.
    lsBoulders.push({dodeca,r:rad,bg:t0,stagger,seed:seedB,simT:0,settledT:0,fadeT:0,rot:0,bounces:0,whistled:false,pace:sp,
      x:bx,y:by,z:bz,vx:bvx,vy:vy0,vz:bvz,
      impT:pred?pred.t:0,impX:pred?pred.x:bx,impZ:pred?pred.z:bz,_target:0});
  }
  lsBursts.push({x,z,t0,warned:false});
}

/* one fixed physics step for a single boulder. returns true if it bounced this step (used for FX + the near-player thud). */
function lsStep(b){
  b.simT+=LS_DT;
  if(b.settledT>=LS_SETTLE_TIME)return false;    // at rest: no more physics, just fading (handled in updateLandslides)
  const rolling=b.simT-b.stagger<LS_ROLL_TIME;   // still bounding along at its pace, or run out of steam
  b.vy-=LS_GRAV*LS_DT;
  b.x+=b.vx*LS_DT;b.y+=b.vy*LS_DT;b.z+=b.vz*LS_DT;
  const gy=baseH(b.x,b.z)+b.r;                   // deterministic ground -- see the note above on baseH vs groundAt
  let bounced=false;
  if(b.y<=gy){
    b.y=gy;
    const hop=rolling?LS_HOP_MIN+LS_HOP_R*b.r:0;
    if(b.vy<-LS_BOUNCE_MIN_VY||hop>0){
      bounced=b.vy<-LS_BOUNCE_MIN_VY;if(bounced)b.bounces++;
      b.vy=Math.min(LS_BOUNCE_MAX_UP,Math.max(hop,-b.vy*LS_REST));   // hop: it bounds along like the tumbleweed, never just slides
      b.vx*=LS_BOUNCE_FRIC;b.vz*=LS_BOUNCE_FRIC;
      // seeded wobble: a pure hash of this boulder's own seed + bounce number, so every camper gets the exact
      // same nudge on the exact same bounce no matter how many real frames it took them to get there
      if(bounced&&hash2(b.seed,b.bounces*97+13)<LS_KICK_CHANCE){
        const ka=hash2(b.seed,b.bounces*97+59)*Math.PI*2,kmag=LS_KICK_SPEED*(0.4+hash2(b.seed,b.bounces*97+101)*0.6);
        b.vx+=Math.cos(ka)*kmag;b.vz+=Math.sin(ka)*kmag;
      }
    }else b.vy=0;
    const e=0.6,gx=(baseH(b.x+e,b.z)-baseH(b.x-e,b.z))/(2*e),gz=(baseH(b.x,b.z+e)-baseH(b.x,b.z-e))/(2*e);
    b.vx-=gx*LS_SLOPE_ACCEL*LS_DT;b.vz-=gz*LS_SLOPE_ACCEL*LS_DT;   // downhill helps a little
    const fr=Math.exp(-(rolling?LS_ROLL_FRIC:LS_STOP_FRIC)*LS_DT);b.vx*=fr;b.vz*=fr;
    let gs=Math.hypot(b.vx,b.vz);
    if(rolling&&gs<b.pace*LS_FLOOR_FRAC&&gs>1e-3){const k=b.pace*LS_FLOOR_FRAC/gs;b.vx*=k;b.vz*=k;gs*=k}   // keeps its pace while it's rolling
    b.settledT=(!rolling&&gs<LS_SETTLE_SPEED&&Math.abs(b.vy)<0.05)?b.settledT+LS_DT:0;
  }else b.settledT=0;
  b.rot+=Math.hypot(b.vx,b.vz)/b.r*LS_DT;
  return bounced;
}

/* boulder-boulder knocks: one pairwise pass over a single burst's boulders, run once per lockstep tick (see
   updateLandslides), so it fires on the same discrete tick for every camper regardless of framerate. `list` is
   already scoped to one burst -- updateLandslides groups by bg and steps + knocks each burst in its own fully
   synchronized lockstep, so two different bursts never interleave here and can't leak timing into each other.
   Scoped to boulders that have already landed at least once (bounces>=1) -- never mid-air -- so it can't perturb
   the pure-ballistic impact prediction (lsPredictImpact) that the landing marker relies on. Pure function of the
   boulders' own position/velocity: no RNG, so no determinism risk beyond the physics itself. */
function lsKnock(list){
  const n=list.length;
  for(let i=0;i<n;i++){
    const a=list[i];if(a.bounces<1||a.settledT>=LS_SETTLE_TIME)continue;
    for(let j=i+1;j<n;j++){
      const bb=list[j];if(bb.bounces<1||bb.settledT>=LS_SETTLE_TIME)continue;
      const dx=bb.x-a.x,dz=bb.z-a.z,min=a.r+bb.r;
      if(Math.abs(dx)>min||Math.abs(dz)>min)continue;         // cheap reject before the sqrt
      const d=Math.hypot(dx,dz);if(d>=min||d<1e-4)continue;
      const nx=dx/d,nz=dz/d,overlap=min-d,wa=bb.r/min,wb=a.r/min;
      a.x-=nx*overlap*wa;a.z-=nz*overlap*wa;bb.x+=nx*overlap*wb;bb.z+=nz*overlap*wb;   // depenetrate, heavier moves less
      const rel=(bb.vx-a.vx)*nx+(bb.vz-a.vz)*nz;
      if(rel<0){                                              // closing in: trade a bit of along-normal speed
        const imp=-(1+LS_KNOCK_REST)*rel/(1/a.r+1/bb.r);
        a.vx-=imp*nx/a.r;a.vz-=imp*nz/a.r;bb.vx+=imp*nx/bb.r;bb.vz+=imp*nz/bb.r;
      }
    }
  }
}

/* natural landslide: deterministic per LS_CELL square and LS_WIN time window, same trick as twPlan() for twisters */
function lsPlan(ci,cj,k){
  const r=mulberry32((((ci+96)*92821+(cj+96))*2246822519^(k*2654435761))>>>0);r();
  const chance=(cj+0.5)*LS_CELL<0?LS_CHANCE_THUMB:LS_CHANCE;   // squares on Big Thumb's side roll far more often
  if(r()>chance)return null;
  const x=(ci+r())*LS_CELL,z=(cj+r())*LS_CELL;
  if(Math.max(Math.abs(x),Math.abs(z))>EDGE-30||campDist(x,z)<70)return null;   // stay off the edge and away from camp
  return{id:ci+','+cj+','+k,x,z,t0:k*LS_WIN+r()*(LS_WIN-2000),seed:((ci+512)*80021+(cj+512)*104729+k*2654435761)>>>0};
}

function lsSound(level){
  if(!AC)return;
  if(!lsRumbleNode){const src=AC.createBufferSource();src.buffer=noiseBuf;src.loop=true;const f=AC.createBiquadFilter();f.type='lowpass';f.frequency.value=130;lsRumbleNode=AC.createGain();lsRumbleNode.gain.value=0;src.connect(f).connect(lsRumbleNode).connect(fxBus);src.start()}
  lsRumbleNode.gain.setTargetAtTime(level*0.55,AC.currentTime,0.3);
}
/* the ground-danger whistle: a falling tone + a burst of high hiss timed to about LS_WARN_LEAD, so it finishes
   right around when the boulder lands. g scales it by how close the landing spot is to you. */
function lsWhistle(dist){
  if(!AC)return;
  const g=clamp(1-dist/LS_WARN_DIST,0,1);if(g<=0)return;
  tone(1500,LS_WARN_LEAD*0.92,'sine',0.05+g*0.16,260);
  noise(LS_WARN_LEAD*0.5,2400,0.6,0.05+g*0.12,'highpass');
}

/* the pool: two InstancedMeshes (dodecahedron look / icosahedron look) for boulders, plus one flat ring for the
   ground-danger marker -- every boulder and every marker ever on screen is 3 draw calls total. */
const LS_MAT_A=new T.MeshStandardMaterial({color:0x8a7c6a,flatShading:true,roughness:1}),LS_MAT_B=new T.MeshStandardMaterial({color:0x6f5a46,flatShading:true,roughness:1});
const lsMeshA=new T.InstancedMesh(new T.IcosahedronGeometry(1,0),LS_MAT_A,LS_POOL_CAP),lsMeshB=new T.InstancedMesh(new T.DodecahedronGeometry(1,0),LS_MAT_B,LS_POOL_CAP);
for(const im of[lsMeshA,lsMeshB]){im.castShadow=im.receiveShadow=true;im.frustumCulled=false;im.instanceMatrix.setUsage(T.DynamicDrawUsage);scene.add(im)}
const LS_MARK_MAT=new T.MeshBasicMaterial({color:0xff4422,transparent:true,opacity:0.5,depthWrite:false,side:T.DoubleSide});
const lsMarkMesh=new T.InstancedMesh(new T.RingGeometry(0.65,1,20),LS_MARK_MAT,LS_POOL_CAP);
lsMarkMesh.frustumCulled=false;lsMarkMesh.instanceMatrix.setUsage(T.DynamicDrawUsage);scene.add(lsMarkMesh);
const lsMarkQuat=new T.Quaternion().setFromAxisAngle(new T.Vector3(1,0,0),-Math.PI/2);   // ring geometry is flat in XY -- tip it flat onto the ground (XZ)

const lsQ=new T.Quaternion();
function lsRender(dt){
  let ia=0,ib=0,imk=0;
  for(const b of lsBoulders){
    const fade=b.settledT>=LS_SETTLE_TIME?clamp(1-b.fadeT/LS_FADE_TIME,0,1):1,s=b.r*fade;
    dummy.position.set(b.x,b.y,b.z);
    /* the roll: a running orientation, turned a little each frame about the axis across its path. (It used to be rebuilt
       from the travel direction every frame, so every bounce that changed its line made the rock snap round.) A
       boulder in the air keeps spinning the way it was. Looks only: never fed back into the physics. */
    if(!b.q){b.q=new T.Quaternion().setFromEuler(new T.Euler(hash2(b.seed,1)*6.3,hash2(b.seed,2)*6.3,0));b.ax=new T.Vector3(1,0,0);b.w=0}
    const gs=Math.hypot(b.vx,b.vz);
    if(b.settledT<LS_SETTLE_TIME&&gs>0.05&&b.y<=baseH(b.x,b.z)+b.r+0.05){b.ax.lerp(lsAxis.set(b.vz/gs,0,-b.vx/gs),Math.min(1,dt*6)).normalize();b.w=gs/b.r}
    else if(b.settledT>=LS_SETTLE_TIME)b.w*=Math.max(0,1-dt*4);
    if(b.w>0.001){lsQ.setFromAxisAngle(b.ax,b.w*dt);b.q.premultiply(lsQ)}
    dummy.quaternion.copy(b.q);
    dummy.scale.setScalar(s);dummy.updateMatrix();
    if(b.dodeca){if(ib<LS_POOL_CAP)lsMeshB.setMatrixAt(ib++,dummy.matrix)}else if(ia<LS_POOL_CAP)lsMeshA.setMatrixAt(ia++,dummy.matrix);

    if(b.bounces===0&&imk<LS_POOL_CAP){
      const lead=b.impT-b._target;
      if(lead>0&&lead<=LS_WARN_LEAD){
        const u=clamp(1-lead/LS_WARN_LEAD,0,1),sc=lerp(LS_MARK_SCALE0,LS_MARK_SCALE1,u)*(b.r+0.4);
        dummy.position.set(b.impX,groundAt(b.impX,b.impZ)+0.06,b.impZ);
        dummy.quaternion.copy(lsMarkQuat);dummy.scale.setScalar(sc);dummy.updateMatrix();
        lsMarkMesh.setMatrixAt(imk++,dummy.matrix);
      }
    }
  }
  dummy.scale.setScalar(0);dummy.updateMatrix();
  for(;ia<LS_POOL_CAP;ia++)lsMeshA.setMatrixAt(ia,dummy.matrix);
  for(;ib<LS_POOL_CAP;ib++)lsMeshB.setMatrixAt(ib,dummy.matrix);
  for(;imk<LS_POOL_CAP;imk++)lsMarkMesh.setMatrixAt(imk,dummy.matrix);
  lsMeshA.instanceMatrix.needsUpdate=true;lsMeshB.instanceMatrix.needsUpdate=true;lsMarkMesh.instanceMatrix.needsUpdate=true;
}

function updateLandslides(dt){
  const T0=twNow(),k=Math.floor(T0/LS_WIN),fx=S.started?P.x:0,fz=S.started?P.z:12;
  const ci=Math.floor(fx/LS_CELL),cj=Math.floor(fz/LS_CELL);
  if(!DIRECTOR_ON&&!ZONE_H&&hazOn('landslide'))for(let i=ci-1;i<=ci+1;i++)for(let j=cj-1;j<=cj+1;j++)for(const kk of[k-1,k]){ // director owns natural landslides when on -- see public/director.js
    const pl=lsPlan(i,j,kk);if(!pl||lsSeen.has(pl.id))continue;
    const e=(T0-pl.t0)/1000;if(e<0||e>LS_LIFE)continue;
    lsSeen.set(pl.id,kk);spawnLandslide(pl.x,pl.z,pl.seed,pl.t0);
  }
  if(k!==lsLastK){lsLastK=k;for(const[id,kk]of lsSeen)if(kk<k-2)lsSeen.delete(id)}   // forget old windows so the map doesn't grow forever

  // lock-step the physics ONE BURST AT A TIME: group boulders by bg (their shared burst-origin time), and for
  // each burst, run every one of ITS boulders forward by the exact same number of LS_DT ticks, with one
  // lsKnock() pass after every tick. Different bursts are processed fully independently (they never interact --
  // lsKnock only ever sees one burst's own list) so their catch-up amounts can differ freely without consequence.
  // Within a burst, though, EVERY member always advances in lockstep together (a boulder that hasn't reached its
  // own stagger delay yet just no-ops when stepped) -- that's what keeps a boulder-boulder knock landing on the
  // same simulated instant for every camper. Gating each boulder by its OWN independent catch-up need (as an
  // earlier version of this did) let two boulders in the same burst drift out of sync WITHIN a single real
  // frame whenever framerate/catch-up timing differed between clients, so a knock could compare their positions
  // at genuinely different simulated moments on different screens -- same total ticks per boulder eventually,
  // but a different knock history along the way, which is exactly the kind of divergence this hazard can't have.
  const groups=new Map();
  for(const b of lsBoulders){let g=groups.get(b.bg);if(!g){g=[];groups.set(b.bg,g)}g.push(b)}
  let loud=0,nearBounce=false;
  for(const[bg,members]of groups){
    let simT=lsClock.get(bg)||0;
    const target=(T0-bg)/1000,need=Math.min(LS_MAX_STEPS,Math.max(0,Math.round((target-simT)/LS_DT)));
    const live=need<LS_LIVE_STEP_CAP;   // false only during a late-joiner's big catch-up: physics runs exactly the same either way, just skip the FX spam
    for(const b of members)b._target=target;   // for the landing marker's lead-time calc (lsRender) and the whistle below
    for(let s=0;s<need;s++){
      simT+=LS_DT;
      for(const b of members){
        if(simT<b.stagger)continue;   // this one's own stagger delay hasn't elapsed yet -- still hovering at spawn, waiting its turn
        if(lsStep(b)&&live){
          const first=b.bounces===1,d=Math.hypot(b.x-fx,b.z-fz);
          if(d<170)puff(b.x,b.y,b.z,b.x,b.z,first?LS_DUST_N:LS_DUST_N_BOUNCE);
          if(d<LS_SHAKE_R*2.4)lsShake=Math.max(lsShake,LS_SHAKE_MAX*clamp(1-d/LS_SHAKE_R,0,1)*(first?1:0.55));
          if(d<45)nearBounce=true;
        }
      }
      lsKnock(members);
    }
    lsClock.set(bg,simT);
    for(const b of members){
      if(b.settledT>=LS_SETTLE_TIME)b.fadeT+=dt;
      if(b.settledT<LS_SETTLE_TIME||b.fadeT<LS_FADE_TIME)loud=Math.max(loud,clamp(1-Math.hypot(b.x-fx,b.z-fz)/160,0,1));
      if(live&&b.bounces===0&&!b.whistled){
        const lead=b.impT-target,dImp=Math.hypot(b.impX-fx,b.impZ-fz);
        if(lead>0&&lead<=LS_WARN_LEAD&&dImp<LS_WARN_DIST){b.whistled=true;lsWhistle(dImp)}
      }
    }
  }
  for(const bg of lsClock.keys())if(!groups.has(bg))lsClock.delete(bg);   // that burst's last boulder is gone -- forget its clock
  if(nearBounce)sfx.thud();
  lsSound(loud);
  lsShake=Math.max(0,lsShake-LS_SHAKE_DECAY*dt);
  if(S.started&&!inTent()&&lsShake>0.002){camera.position.x+=(Math.random()-0.5)*lsShake;camera.position.y+=(Math.random()-0.5)*lsShake}

  // spliced in place (not reassigned via .filter) so the arrays keep the same identity forever -- nothing else has
  // to worry about holding a stale reference to a boulder list that got swapped out from under it
  for(let i=lsBoulders.length-1;i>=0;i--)if(lsBoulders[i].settledT>=LS_SETTLE_TIME&&lsBoulders[i].fadeT>=LS_FADE_TIME)lsBoulders.splice(i,1);
  for(let i=lsBursts.length-1;i>=0;i--)if((T0-lsBursts[i].t0)/1000>=LS_LIFE)lsBursts.splice(i,1);

  for(const bu of lsBursts)if(!bu.warned&&S.started&&Math.hypot(bu.x-fx,bu.z-fz)<LS_WARN_R){
    bu.warned=true;logEv('lsWarn',{x:+P.x.toFixed(1),z:+P.z.toFixed(1),lsx:+bu.x.toFixed(1),lsz:+bu.z.toFixed(1)});toast('Rockslide! Boulders coming from Big Thumb!','bad',5000);
  }

  lsHitT=Math.max(0,lsHitT-dt);
  if(S.started&&!S.ko&&holeDepthHere()<=LS_SAFE_DEPTH){
    for(const b of lsBoulders){
      const dx=P.x-b.x,dz=P.z-b.z,d=Math.hypot(dx,dz),touch=b.r+LS_TOUCH_PAD;
      if(d>=touch||Math.abs(P.y-b.y)>b.r+1.6)continue;
      const speed=Math.min(LS_DMG_SPEED_CAP,Math.hypot(b.vx,b.vy,b.vz));
      if(speed>LS_HURT_SPEED){
        if(lsHitT<=0){
          lsHitT=LS_HIT_GRACE;
          const dmg=Math.max(6,Math.round((speed-LS_HURT_SPEED)*b.r*LS_DMG_K));
          const nx=d>0.05?dx/d:1,nz=d>0.05?dz/d:0,kb=Math.min(22,5+speed*1.1);
          P.kx=nx*kb;P.kz=nz*kb;P.vy=Math.max(P.vy,4+Math.min(8,speed*0.3));P.grounded=false;
          hurt(dmg,'Landslide','A boulder from the rockslide hit you.');
          if(!S.ko)toast(`A boulder hit you! -${dmg} health`,'bad',3000);
        }
      }else{
        const push=touch-d;if(d>0.05){P.x+=dx/d*push;P.z+=dz/d*push}else P.x+=push;   // slow/settled: just solid, push you back out
      }
    }
  }
  lsRender(dt);
}

/* Blender boulders (art/blender/rocks.py): once loaded they replace the pool's geometry -- same instances, same
   unit radius, so the physics, radii and roll are untouched */
modelParts('BoulderA').then(([p])=>{lsMeshA.geometry=p.geometry;lsMeshA.material=p.material}).catch(()=>{});
modelParts('BoulderB').then(([p])=>{lsMeshB.geometry=p.geometry;lsMeshB.material=p.material}).catch(()=>{});
